// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

import {TimelockController} from "@openzeppelin/contracts/governance/TimelockController.sol";

/// @title GovernanceTimelock — timelocked executor for SharedStake protocol governance
/// @notice Wraps OpenZeppelin TimelockController with a 48-hour default delay.
///         This contract holds the GOV role on all protocol contracts.
///         All privileged parameter changes must flow through Governor → Timelock.
///
/// Role model:
///   PROPOSER  — Governor contract (can queue proposals)
///   EXECUTOR  — Governor + guardian multisig (can execute after delay)
///   CANCELLER — Guardian multisig (can cancel malicious proposals)
///
/// Emergency path:
///   GUARDIAN can still `pause()` directly on all contracts without timelock.
///   This ensures fast incident response while keeping parameter changes slow.
contract GovernanceTimelock is TimelockController {
    /// @param minDelay Initial delay in seconds (e.g., 48 hours = 172800).
    /// @param proposers Addresses that can schedule operations (Governor).
    /// @param executors Addresses that can execute operations (Governor + guardian).
    /// @param admin Admin address for setup (renounced after wiring).
    constructor(
        uint256 minDelay,
        address[] memory proposers,
        address[] memory executors,
        address admin
    ) TimelockController(minDelay, proposers, executors, admin) {}
}

contracts/v2/governance/ReferralRegistry.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import {Errors} from "../lib/Errors.sol";

interface IStTokenReferral {
    function transferShares(address to, uint256 sharesAmount) external returns (uint256 tokensAmount);
    function sharesOf(address account) external view returns (uint256);
    function getPooledEthByShares(uint256 sharesAmount) external view returns (uint256);
}

/// @title ReferralRegistry — on-chain referral attribution for SharedStake
/// @notice Tracks who referred whom, total referred stake per referrer, and
///         accrued referral fees. Fees are denominated in StToken shares so
///         they auto-compound with the exchange rate.
///
///         Fee split (configurable by GOV):
///           treasury      = fee * (10000 - referralBps - operatorBps) / 10000
///           operator      = fee * operatorBps / 10000
///           referralPool  = fee * referralBps / 10000
///
///         Referral fee is further split between individual referrers based on
///         their proportion of total referred stake.
///
/// Roles:
///   GOV      — set fee params, pause
///   ROUTER   — record deposits (only StakingRouter)
///   FEE_CTL  — deposit fee shares into registry (only FeeController)
contract ReferralRegistry is AccessControl, ReentrancyGuard {
    bytes32 public constant GOV = keccak256("GOV");
    bytes32 public constant ROUTER = keccak256("ROUTER");
    bytes32 public constant FEE_CTL = keccak256("FEE_CTL");

    // ── State ─────────────────────────────────────────────────────────────────
    struct ReferralRecord {
        uint256 totalReferredEth;   // cumulative ETH staked via this referrer
        uint256 totalReferredShares;  // cumulative shares minted for referrals
        uint256 lastRecordedAt;     // timestamp of last activity
    }

    struct ReferrerEarnings {
        uint256 accruedShares;      // unclaimed fee shares
        uint256 claimedShares;      // lifetime claimed
    }

    // referrer => referee => record
    mapping(address => mapping(address => ReferralRecord)) public records;
    // referrer => earnings
    mapping(address => ReferrerEarnings) public earnings;
    // referrer => total referred ETH
    mapping(address => uint256) public referrerTotalReferredEth;
    // referrer => total referred shares
    mapping(address => uint256) public referrerTotalReferredShares;

    uint256 public referralFeeBps = 500;         // 5% of protocol fees
    uint256 public constant MAX_REFERRAL_BPS = 2000; // 20% cap
    uint256 public constant MAX_DISTRIBUTION_BATCH = 256;
    uint256 public totalAccruedReferralShares;  // total unclaimed in contract
    uint256 public totalAllocatedReferralShares; // total assigned to referrers but unclaimed

    IStTokenReferral public stToken;

    // ── Events ────────────────────────────────────────────────────────────────
    event DepositRecorded(address indexed referrer, address indexed referee, uint256 ethAmount, uint256 shares);
    event ReferralFeeDeposited(uint256 shares);
    event ReferralFeeClaimed(address indexed referrer, uint256 shares, uint256 ethValue);
    event ReferralFeeBpsSet(uint256 newBps);

    // ── Errors ────────────────────────────────────────────────────────────────
    error ReferralFeeTooHigh();
    error NothingToClaim();
    error SelfReferral();
    error InsufficientBacking(uint256 availableShares, uint256 requiredShares);
    error DistributionExceedsAvailable(uint256 requested, uint256 available);
    error BatchTooLarge(uint256 provided, uint256 maxAllowed);

    constructor(address _gov, address _stToken) {
        if (_gov == address(0) || _stToken == address(0)) revert Errors.ZeroAddress();
        _grantRole(DEFAULT_ADMIN_ROLE, _gov);
        _grantRole(GOV, _gov);
        stToken = IStTokenReferral(_stToken);
    }

    // ── Core functions ─────────────────────────────────────────────────────────

    /// @notice Called by StakingRouter on every deposit that includes a referral.
    ///         Records the stake attribution for fee distribution.
    function recordDeposit(
        address referrer,
        address referee,
        uint256 ethAmount,
        uint256 shares
    ) external onlyRole(ROUTER) {
        if (referrer == referee) revert SelfReferral();
        if (referrer == address(0)) return; // no-op for missing referral

        ReferralRecord storage rec = records[referrer][referee];
        rec.totalReferredEth += ethAmount;
        rec.totalReferredShares += shares;
        rec.lastRecordedAt = block.timestamp;

        referrerTotalReferredEth[referrer] += ethAmount;
        referrerTotalReferredShares[referrer] += shares;

        emit DepositRecorded(referrer, referee, ethAmount, shares);
    }

    /// @notice Called by FeeController to deposit fee shares into the referral pool.
    function depositReferralFeeShares(uint256 shares) external onlyRole(FEE_CTL) {
        uint256 nextTotalAccrued = totalAccruedReferralShares + shares;
        uint256 availableShares = stToken.sharesOf(address(this));
        if (availableShares < nextTotalAccrued) {
            revert InsufficientBacking(availableShares, nextTotalAccrued);
        }

        totalAccruedReferralShares = nextTotalAccrued;
        emit ReferralFeeDeposited(shares);
    }

    /// @notice Claim accrued referral fees. Converts shares to ETH at current rate.
    function claimReferralFees() external nonReentrant {
        ReferrerEarnings storage ear = earnings[msg.sender];
        uint256 accrued = ear.accruedShares;
        if (accrued == 0) revert NothingToClaim();

        ear.accruedShares = 0;
        ear.claimedShares += accrued;
        totalAllocatedReferralShares -= accrued;
        totalAccruedReferralShares -= accrued;

        uint256 ethValue = stToken.getPooledEthByShares(accrued);
        stToken.transferShares(msg.sender, accrued);

        emit ReferralFeeClaimed(msg.sender, accrued, ethValue);
    }

    // ── View functions ─────────────────────────────────────────────────────────

    /// @notice Get a referrer's total referred ETH and share amounts.
    function getReferrerStats(address referrer)
        external
        view
        returns (uint256 totalEth, uint256 totalShares, uint256 accruedFees)
    {
        totalEth = referrerTotalReferredEth[referrer];
        totalShares = referrerTotalReferredShares[referrer];
        accruedFees = earnings[referrer].accruedShares;
    }

    /// @notice Get a specific referral pair's record.
    function getRecord(address referrer, address referee)
        external
        view
        returns (ReferralRecord memory)
    {
        return records[referrer][referee];
    }

    /// @notice Preview claimable ETH value for a referrer at current exchange rate.
    function previewClaimableEth(address referrer) external view returns (uint256) {
        uint256 shares = earnings[referrer].accruedShares;
        return stToken.getPooledEthByShares(shares);
    }

    // ── Admin ─────────────────────────────────────────────────────────────────

    function setReferralFeeBps(uint256 _bps) external onlyRole(GOV) {
        if (_bps > MAX_REFERRAL_BPS) revert ReferralFeeTooHigh();
        referralFeeBps = _bps;
        emit ReferralFeeBpsSet(_bps);
    }

    function setStToken(address _stToken) external onlyRole(GOV) {
        if (_stToken == address(0)) revert Errors.ZeroAddress();
        stToken = IStTokenReferral(_stToken);
    }

    // ── Internal ──────────────────────────────────────────────────────────────

    /// @notice Distribute a batch of fee shares among referrers proportionally.
    ///         Called by FEE_CTL or can be permissionlessly called by anyone
    ///         with off-chain computed proportional allocations.
    function distributeFees(
        address[] calldata referrers,
        uint256[] calldata shares
    ) external onlyRole(FEE_CTL) {
        uint256 len = referrers.length;
        if (len > MAX_DISTRIBUTION_BATCH) revert BatchTooLarge(len, MAX_DISTRIBUTION_BATCH);
        require(len == shares.length, "Length mismatch");

        uint256 batchTotal;
        for (uint256 i = 0; i < len; ++i) {
            batchTotal += shares[i];
        }

        uint256 availableToAllocate = totalAccruedReferralShares - totalAllocatedReferralShares;
        if (batchTotal > availableToAllocate) revert DistributionExceedsAvailable(batchTotal, availableToAllocate);

        totalAllocatedReferralShares += batchTotal;
        for (uint256 i = 0; i < len; ++i) {
            earnings[referrers[i]].accruedShares += shares[i];
        }
    }
}

