        Active,
        DepositsPaused,
        Stopped
    }

    struct ModuleView {
        address module;
        ModuleStatus status;
        uint16 targetShareBps;
        uint16 maxShareBps;
        uint16 moduleFeeBps;
        uint16 treasuryFeeBps;
